import pathlib,base64,hashlib,json,zipfile,shutil,subprocess,os,time
root=pathlib.Path("/home/ubuntu/otzaria-wave3-saved-results-reveal-20261127/controls/attempt-1")
assert not root.exists()
floor=1342177280; cap=104857600
assert shutil.disk_usage(root.parent.parent).free > floor+cap
root.mkdir(parents=True)
b=base64.b64decode("")
assert len(b)==34181 and hashlib.sha256(b).hexdigest()=="4ce3932568c6df6fbcec1bc4f3fef30b9a8bb99a70ecc68326ee45527dfa007c"
(root/"INPUTS.zip").write_bytes(b)
with zipfile.ZipFile(root/"INPUTS.zip") as z:
 for n in z.namelist():
  p=pathlib.PurePosixPath(n); assert not p.is_absolute() and ".." not in p.parts
 z.extractall(root/"inputs")
for row in json.loads((root/"inputs/INPUTS.json").read_text()):
 raw=(root/"inputs"/row["path"]).read_bytes()
 assert len(raw)==row["bytes"] and hashlib.sha256(raw).hexdigest()==row["sha256"]
swift=shutil.which("swiftc"); assert swift
result={"source_boundary":"Actual passive source plus Foundation Observation; UIKit/AppIntent/Core/native NOT_RUN","swiftc":swift,"started":time.time(),"free_before":shutil.disk_usage(root).free,"inputs_sha256":"4ce3932568c6df6fbcec1bc4f3fef30b9a8bb99a70ecc68326ee45527dfa007c","runs":[]}
(root/"module-cache").mkdir()
for name, rel in [("initial","evidence/initial-load-lifetime/OriginalSavedResultsLoadLifetime.swift"),("candidate","candidate/Source/ChavrusaText/Bookmarks/OriginalSavedResultsLoadLifetime.swift")]:
 command=[swift,"-parse-as-library","-module-cache-path",str(root/"module-cache"),str(root/"inputs"/rel),str(root/"inputs/controls/LoadLifetimeTests.swift"),"-o",str(root/name)]
 p=subprocess.run(command,capture_output=True,text=True,timeout=90)
 (root/(name+"-compile.stdout")).write_text(p.stdout);(root/(name+"-compile.stderr")).write_text(p.stderr)
 row={"name":name,"argv":command,"compile_exit":p.returncode}
 if p.returncode==0:
  r=subprocess.run([str(root/name)],capture_output=True,text=True,timeout=15)
  (root/(name+".stdout")).write_text(r.stdout);(root/(name+".stderr")).write_text(r.stderr)
  row.update(exit=r.returncode,summary=r.stdout[-500:])
 result["runs"].append(row)
 assert shutil.disk_usage(root).free > floor
 allocated=sum(p.stat().st_size for p in root.rglob("*") if p.is_file())
 assert allocated < cap
parses=[]
for p in (root/"inputs/candidate").rglob("*.swift"):
 command=[swift,"-frontend","-parse","-target","arm64-apple-ios27.0",str(p)]
 r=subprocess.run(command,capture_output=True,text=True,timeout=20)
 log=root/("parse-"+hashlib.sha256(str(p).encode()).hexdigest()[:12]+".stderr");log.write_text(r.stderr)
 parses.append({"source":str(p.relative_to(root/"inputs")),"exit":r.returncode,"stderr":log.name})
result.update(parses=parses,free_after=shutil.disk_usage(root).free,finished=time.time())
(root/"RESULT.json").write_text(json.dumps(result,indent=2)+"\n")
print(json.dumps(result))
